import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  const timelines = [];

  // Design tokens
  const colors = {
    background: '#0b0b10',
    surface: '#101017',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  const typo = {
    hero: {
      family: 'Lora',
      fontSize: 124,
      fontWeight: 600,
      letterSpacing: -0.01,
    },
    subhead: {
      family: 'JetBrains Mono',
      fontSize: 40,
      fontWeight: 400,
      letterSpacing: 0.02,
    },
    caption: {
      family: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 700,
      letterSpacing: 0.12,
    },
  };

  // Backdrop plane with gradient base
  const backdropGeo = new THREE.PlaneGeometry(7, 5.5);
  const backdropMat = new THREE.MeshBasicMaterial({
    color: new THREE.Color(colors.background),
  });
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -1.5;
  root.add(backdrop);

  // Caption: "NOVA ATELIER / CALIBRE PROGRAM"
  const caption = ctx.fontAtlas('NOVA ATELIER / CALIBRE PROGRAM', {
    font: typo.caption.family,
    fontSize: typo.caption.fontSize,
    fontWeight: typo.caption.fontWeight,
    letterSpacing: typo.caption.letterSpacing,
    color: colors.paper,
  });
  caption.position.y = 1.15;
  root.add(caption);

  // Hero text group with parallax depth
  const heroGroup = new THREE.Group();
  heroGroup.position.y = 0.4;
  heroGroup.scale.set(1.04, 1.04, 1.04); // Initial scale for weighted-settle

  const heroText = 'TIME, MACHINED.';
  const heroMesh = ctx.fontAtlas(heroText, {
    font: typo.hero.family,
    fontSize: typo.hero.fontSize,
    fontWeight: typo.hero.fontWeight,
    letterSpacing: typo.hero.letterSpacing,
    color: colors.paper,
  });

  // Apply per-word z-depth offsets for parallax
  // "TIME," (indices 0-4) → z = 0.12
  // " " (index 5) → z = 0.0
  // "MACHINED." (indices 6-14) → z = -0.12
  if (heroMesh.children) {
    heroMesh.children.forEach((glyph, idx) => {
      if (idx <= 4) {
        glyph.position.z = 0.12;
      } else if (idx === 5) {
        glyph.position.z = 0.0;
      } else {
        glyph.position.z = -0.12;
      }
    });
  }

  heroGroup.add(heroMesh);
  root.add(heroGroup);

  // Accent underline plane
  const underlineGeo = new THREE.PlaneGeometry(2.6, 0.045);
  const underlineMat = new THREE.MeshBasicMaterial({
    color: new THREE.Color(colors.accent),
  });
  const underline = new THREE.Mesh(underlineGeo, underlineMat);
  underline.position.y = -0.05;
  underline.scale.x = 0; // Starts at scaleX 0
  root.add(underline);

  // Subhead: "Every calibre begins as a solid billet."
  const subhead = ctx.fontAtlas('Every calibre begins as a solid billet.', {
    font: typo.subhead.family,
    fontSize: typo.subhead.fontSize,
    fontWeight: typo.subhead.fontWeight,
    letterSpacing: typo.subhead.letterSpacing,
    color: colors.paper,
  });
  subhead.position.y = -0.65;
  subhead.material.transparent = true;
  subhead.material.opacity = 0;
  root.add(subhead);

  // Main animation timeline
  const timeline = gsap.timeline({ paused: false });
  timelines.push(timeline);

  // Subhead fade-up: opacity 0→1, y+0.2→0 over 500ms
  timeline.to(
    subhead.position,
    { y: -0.65, duration: 0.5, ease: 'power2.out' },
    0
  );
  timeline.to(
    subhead.material,
    { opacity: 1, duration: 0.5, ease: 'power2.out' },
    0
  );

  // Apply kinetic-text cinematic primitive
  // Per-glyph: y +0.35→0, opacity 0→1, 700ms each, 60ms stagger, cubic-bezier(0.215,0.61,0.355,1)
  ctx.primitives['kinetic-text'](heroGroup, {
    staggerMs: 60,
    riseUnits: 0.35,
  });

  // Calculate timing: kinetic entrance 700ms + (glyphCount-1) * 60ms stagger
  const glyphCount = heroText.length; // 15 characters
  const kinematicDuration = 0.7;
  const staggerInterval = 0.06;
  const lastGlyphFinishTime = kinematicDuration + (glyphCount - 1) * staggerInterval;

  // Weighted-settle: scale 1.04→1.0 over 900ms cubic-bezier(0.165,0.84,0.44,1)
  // Triggered when final glyph lands
  timeline.to(
    heroGroup.scale,
    { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'cubic.out' },
    lastGlyphFinishTime
  );

  // Underline scaleX animation: 0→1 over 500ms, starts 120ms after last glyph lands
  timeline.to(
    underline.scale,
    { x: 1, duration: 0.5, ease: 'cubic.out' },
    lastGlyphFinishTime + 0.12
  );

  // Cleanup
  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    backdropGeo.dispose();
    backdropMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();
  };

  return root;
}
